import unittest

class TestRollingMax(unittest.TestCase):
    def test_basic_increasing_sequence(self):
        self.assertEqual(rolling_max([1, 2, 3, 2, 3, 4, 2]), [1, 2, 3, 3, 3, 4, 4])

    def test_empty_list(self):
        self.assertEqual(rolling_max([]), [])

    def test_single_element_list(self):
        self.assertEqual(rolling_max([5]), [5])

    def test_all_same_elements(self):
        self.assertEqual(rolling_max([7, 7, 7, 7]), [7, 7, 7, 7])

    def test_decreasing_sequence(self):
        self.assertEqual(rolling_max([5, 4, 3, 2, 1]), [5, 5, 5, 5, 5])

    def test_sequence_with_negatives(self):
        self.assertEqual(rolling_max([-1, -3, -2, 0, -1]), [-1, -1, -1, 0, 0])

    def test_alternating_high_low(self):
        self.assertEqual(rolling_max([3, 1, 4, 1, 5, 1, 6]), [3, 3, 4, 4, 5, 5, 6])

    def test_long_increasing_sequence(self):
        self.assertEqual(rolling_max(list(range(10))), list(range(10)))

    def test_long_decreasing_sequence(self):
        self.assertEqual(rolling_max(list(range(10, 0, -1))), [10]*10)

    def test_two_elements_equal(self):
        self.assertEqual(rolling_max([2, 2]), [2, 2])

    def test_large_numbers(self):
        self.assertEqual(rolling_max([10**6, 10**7, 10**5]), [10**6, 10**7, 10**7])

    def test_alternating_pos_neg(self):
        self.assertEqual(rolling_max([1, -1, 2, -2, 3, -3]), [1, 1, 2, 2, 3, 3])

    def test_all_negative_sequence(self):
        self.assertEqual(rolling_max([-5, -4, -3, -6, -7]), [-5, -4, -3, -3, -3])

    def test_single_peak(self):
        self.assertEqual(rolling_max([1, 2, 3, 10, 2, 1]), [1, 2, 3, 10, 10, 10])

    def test_flat_then_increasing(self):
        self.assertEqual(rolling_max([2, 2, 2, 3, 4]), [2, 2, 2, 3, 4])
