import unittest

class TestEncodeDecodeShift(unittest.TestCase):

    def test_encode_basic(self):
        self.assertEqual(encode_shift("abc"), "fgh")

    def test_decode_basic(self):
        self.assertEqual(decode_shift("fgh"), "abc")

    def test_encode_wrap_around(self):
        self.assertEqual(encode_shift("xyz"), "cde")

    def test_decode_wrap_around(self):
        self.assertEqual(decode_shift("cde"), "xyz")

    def test_encode_full_alphabet(self):
        self.assertEqual(encode_shift("abcdefghijklmnopqrstuvwxyz"), "fghijklmnopqrstuvwxyzabcde")

    def test_decode_full_alphabet(self):
        self.assertEqual(decode_shift("fghijklmnopqrstuvwxyzabcde"), "abcdefghijklmnopqrstuvwxyz")

    def test_encode_single_letter(self):
        self.assertEqual(encode_shift("a"), "f")

    def test_decode_single_letter(self):
        self.assertEqual(decode_shift("f"), "a")

    def test_encode_repeated_chars(self):
        self.assertEqual(encode_shift("aaaaa"), "fffff")

    def test_decode_repeated_chars(self):
        self.assertEqual(decode_shift("fffff"), "aaaaa")

    def test_encode_empty_string(self):
        self.assertEqual(encode_shift(""), "")

    def test_decode_empty_string(self):
        self.assertEqual(decode_shift(""), "")

    def test_encode_non_continuous_letters(self):
        self.assertEqual(encode_shift("azbycx"), "feuqhd")

    def test_decode_non_continuous_letters(self):
        self.assertEqual(decode_shift("feuqhd"), "azbycx")

    def test_encode_long_string(self):
        long_str = "thequickbrownfoxjumpsoverthelazydog"
        encoded = encode_shift(long_str)
        self.assertEqual(encoded, "".join([chr(((ord(ch) + 5 - ord("a")) % 26) + ord("a")) for ch in long_str]))
        self.assertEqual(decode_shift(encoded), long_str)

if __name__ == "__main__":
