def test_fibfib_iterative_equivalence():
    def iterative_fibfib(n):
        if n == 0: return 0
        if n == 1: return 0
        if n == 2: return 1
        seq = [0, 0, 1]
        for i in range(3, n + 1):
            seq.append(seq[i - 1] + seq[i - 2] + seq[i - 3])
        return seq[n]
    for i in range(30):
        assert fibfib(i) == iterative_fibfib(i)

def test_fibfib_type_and_nonnegative():
    for i in range(20):
        result = fibfib(i)
        assert isinstance(result, int)
