import unittest

class TestSortArray(unittest.TestCase):

    def test_empty_array(self):
        self.assertEqual(sort_array([]), [])

    def test_single_element_array(self):
        self.assertEqual(sort_array([5]), [5])

    def test_sum_odd_ascending_sort(self):
        self.assertEqual(sort_array([2, 4, 3, 0, 1, 5]), [0, 1, 2, 3, 4, 5])

    def test_sum_even_descending_sort(self):
        self.assertEqual(sort_array([2, 4, 3, 0, 1, 5, 6]), [6, 5, 4, 3, 2, 1, 0])

    def test_original_array_unchanged(self):
        arr = [3, 1, 4, 2]
        copy_arr = arr[:]
        _ = sort_array(arr)
        self.assertEqual(arr, copy_arr)

    def test_all_equal_elements(self):
        self.assertEqual(sort_array([7,7,7,7]), [7,7,7,7])

    def test_two_elements_sum_odd(self):
        self.assertEqual(sort_array([1,2]), [1,2])

    def test_two_elements_sum_even(self):
        self.assertEqual(sort_array([4,4]), [4,4])

    def test_large_numbers_sum_odd(self):
        self.assertEqual(sort_array([1000000, 3, 5, 2]), [2, 3, 5, 1000000])

    def test_large_numbers_sum_even(self):
        self.assertEqual(sort_array([1000000, 3, 5, 1000000]), [1000000, 1000000, 5, 3])

    def test_sum_odd_with_zero(self):
        self.assertEqual(sort_array([0, 4, 2, 6]), [0, 2, 4, 6])

    def test_sum_even_with_zero(self):
        self.assertEqual(sort_array([0, 1, 2, 0]), [2, 1, 0, 0])

    def test_sorted_ascending_input_sum_odd(self):
        self.assertEqual(sort_array([1,2,3,4]), [1,2,3,4])

    def test_sorted_descending_input_sum_even(self):
        self.assertEqual(sort_array([4,3,2,4]), [4,4,3,2])

    def test_long_array_mixed_values(self):
        arr = [5,3,8,6,1,0,9]
        expected = sorted(arr, reverse=(arr[0]+arr[-1])%2==0)
        self.assertEqual(sort_array(arr), expected)

