        self.assertEqual(encrypt('hi'), 'lm')

    def test_basic_shift_asdfghjkl(self):
        self.assertEqual(encrypt('asdfghjkl'), 'ewhjklnop')

    def test_basic_shift_gf(self):
        self.assertEqual(encrypt('gf'), 'kj')

    def test_basic_shift_et(self):
        self.assertEqual(encrypt('et'), 'ix')

    def test_empty_string(self):
        self.assertEqual(encrypt(''), '')

    def test_non_alpha_characters(self):
        self.assertEqual(encrypt('hi!'), 'lm!')

    def test_mixed_alpha_and_numbers(self):
        self.assertEqual(encrypt('abc123'), 'efg123')

    def test_uppercase_unchanged(self):
        self.assertEqual(encrypt('Hi'), 'Lm')

    def test_full_alphabet(self):
        self.assertEqual(encrypt('abcdefghijklmnopqrstuvwxyz'), 'efghijklmnopqrstuvwxyzabcd')

    def test_repeated_chars(self):
        self.assertEqual(encrypt('aaa'), 'eee')

    def test_single_char_a(self):
        self.assertEqual(encrypt('a'), 'e')

    def test_single_char_z(self):
        self.assertEqual(encrypt('z'), 'd')

    def test_string_with_spaces(self):
        self.assertEqual(encrypt('a b c'), 'e f g')

    def test_string_with_punctuation(self):
        self.assertEqual(encrypt('hello, world!'), 'lipps, asvph!')

    def test_string_with_newlines(self):
        self.assertEqual(encrypt('hi\net'), 'lm\nix')


if __name__ == '__main__':
    unittest.main()

