        self.assertEqual(choose_num(15, 15), -1)

    def test_even_upper_bound(self):
        self.assertEqual(choose_num(4, 8), 8)

    def test_odd_upper_bound_returns_previous_even(self):
        self.assertEqual(choose_num(4, 7), 6)

    def test_lower_bound_equals_upper_bound_odd(self):
        self.assertEqual(choose_num(7, 7), -1)

    def test_lower_bound_equals_upper_bound_even(self):
        self.assertEqual(choose_num(8, 8), 8)

    def test_large_range(self):
        self.assertEqual(choose_num(1, 100), 100)

    def test_large_range_odd_upper_bound(self):
