import unittest

class TestMinSubArraySum(unittest.TestCase):

    def test_positive_and_negative_mix(self):
        self.assertEqual(minSubArraySum([2, 3, 4, 1, 2, 4]), 1)

    def test_all_negative_numbers(self):
        self.assertEqual(minSubArraySum([-1, -2, -3]), -6)

    def test_single_element_positive(self):
        self.assertEqual(minSubArraySum([5]), 5)

    def test_single_element_negative(self):
        self.assertEqual(minSubArraySum([-10]), -10)

    def test_all_positive_numbers(self):
        self.assertEqual(minSubArraySum([1, 2, 3, 4, 5]), 1)

    def test_mixed_signs_with_zero(self):
        self.assertEqual(minSubArraySum([0, -1, 2, -3, 4]), -3)

    def test_min_subarray_at_end(self):
        self.assertEqual(minSubArraySum([10, 20, -30]), -30)

    def test_min_subarray_at_start(self):
        self.assertEqual(minSubArraySum([-5, 1, 2, 3]), -5)

    def test_min_subarray_in_middle(self):
        self.assertEqual(minSubArraySum([10, -10, -10, 10]), -20)

    def test_multiple_min_subarrays(self):
        self.assertEqual(minSubArraySum([1, -1, 1, -1]), -1)

    def test_large_numbers(self):
        self.assertEqual(minSubArraySum([1000000, -1000001, 1000000]), -1000001)

    def test_alternating_signs(self):
        self.assertEqual(minSubArraySum([1, -2, 3, -4, 5, -6]), -6)

    def test_all_zeros(self):
        self.assertEqual(minSubArraySum([0, 0, 0, 0]), 0)

    def test_empty_input_raises(self):
        with self.assertRaises(IndexError):
            minSubArraySum([])

    def test_large_input(self):
        arr = [1]*10000 + [-5000] + [1]*10000
        self.assertEqual(minSubArraySum(arr), -5000)

