import unittest

class TestSplitWords(unittest.TestCase):

    def test_split_on_spaces(self):
        self.assertEqual(split_words("Hello world!"), ["Hello", "world!"])

    def test_split_on_commas(self):
        self.assertEqual(split_words("Hello,world!"), ["Hello", "world!"])

    def test_count_lowercase_odd_order_letters(self):
        self.assertEqual(split_words("abcdef"), 3)

    def test_empty_string_returns_zero(self):
        self.assertEqual(split_words(""), 0)

    def test_only_commas_splits_correctly(self):
        self.assertEqual(split_words("one,two,three"), ["one", "two", "three"])

    def test_only_spaces_splits_correctly(self):
        self.assertEqual(split_words("one two three"), ["one", "two", "three"])

    def test_no_spaces_no_commas_count_odd(self):
        self.assertEqual(split_words("xyz"), 0)

    def test_mixed_spaces_and_commas_prioritizes_spaces(self):
        self.assertEqual(split_words("a,b c"), ["a,b", "c"])

    def test_uppercase_letters_not_counted(self):
        self.assertEqual(split_words("AbCdEf"), 3)

    def test_non_alpha_characters_ignored_in_count(self):
        self.assertEqual(split_words("a1b2c3"), 3)

    def test_all_uppercase_no_spaces_no_commas(self):
        self.assertEqual(split_words("ABCDEF"), 0)

    def test_string_with_tabs_splits_on_spaces_not_tabs(self):
        self.assertEqual(split_words("word1\tword2"), ["word1\tword2"])

    def test_string_with_multiple_spaces(self):
        self.assertEqual(split_words("hello   world"), ["hello", "world"])

    def test_string_with_leading_trailing_spaces(self):
        self.assertEqual(split_words("  hello world  "), ["hello", "world"])

    def test_string_with_commas_and_spaces_returns_split_on_spaces(self):
        self.assertEqual(split_words("one, two, three"), ["one,", "two,", "three"])

if __name__ == '__main__':
    unittest.main()

