import unittest

class TestCanArrange(unittest.TestCase):

    def test_decreasing_element_in_middle(self):
        self.assertEqual(can_arrange([1, 2, 4, 3, 5]), 3)

    def test_strictly_increasing(self):
        self.assertEqual(can_arrange([1, 2, 3]), -1)

    def test_decreasing_at_end(self):
        self.assertEqual(can_arrange([1, 2, 3, 2]), 3)

    def test_decreasing_at_start(self):
        self.assertEqual(can_arrange([5, 4, 6, 7]), 1)

    def test_multiple_decreases_take_last(self):
        self.assertEqual(can_arrange([10, 9, 11, 7]), 3)

    def test_single_element(self):
        self.assertEqual(can_arrange([42]), -1)

    def test_empty_array(self):
        self.assertEqual(can_arrange([]), -1)

    def test_large_increasing_then_decrease_once(self):
        self.assertEqual(can_arrange(list(range(100)) + [50]), 100)

    def test_two_elements_decreasing(self):
        self.assertEqual(can_arrange([2, 1]), 1)

    def test_two_elements_increasing(self):
        self.assertEqual(can_arrange([1, 2]), -1)

    def test_alternating_values(self):
        self.assertEqual(can_arrange([1, 3, 2, 4, 3, 5]), 4)

    def test_decreasing_elements_far_apart(self):
        self.assertEqual(can_arrange([1, 5, 6, 2, 10, 9]), 5)

    def test_long_strictly_increasing(self):
        self.assertEqual(can_arrange(list(range(1, 1000))), -1)

    def test_long_with_last_element_decreasing(self):
        arr = list(range(1, 1000))
        arr.append(500)
        self.assertEqual(can_arrange(arr), 1000)

    def test_decreasing_at_second_element(self):
        self.assertEqual(can_arrange([10, 9, 11, 12]), 1)

