import unittest

class TestSpecialFactorial(unittest.TestCase):

    def test_smallest_input(self):
        self.assertEqual(special_factorial(1), 1)

    def test_input_two(self):
        self.assertEqual(special_factorial(2), 2)

    def test_input_three(self):
        self.assertEqual(special_factorial(3), 12)

    def test_input_four(self):
        self.assertEqual(special_factorial(4), 288)

    def test_input_five(self):
        self.assertEqual(special_factorial(5), 34560)

    def test_input_six(self):
        self.assertEqual(special_factorial(6), 24883200)

    def test_consistency_for_sequential(self):
        prev = 1
        for n in range(1, 8):
            val = special_factorial(n)
            self.assertTrue(val > prev)
            prev = val

    def test_type_error_for_non_integer(self):
        with self.assertRaises(TypeError):
            special_factorial("4")

    def test_value_error_for_zero(self):
        with self.assertRaises(ValueError):
            special_factorial(0)

    def test_value_error_for_negative(self):
        with self.assertRaises(ValueError):
            special_factorial(-3)

    def test_large_input_8(self):
        expected = 24883200 * 7 * 8 * 6  # approximate sanity check (not exact)
        result = special_factorial(8)
        self.assertTrue(result > expected)

    def test_input_is_integer_float(self):
        with self.assertRaises(TypeError):
            special_factorial(4.0)

    def test_input_is_none(self):
        with self.assertRaises(TypeError):
            special_factorial(None)

    def test_input_is_list(self):
        with self.assertRaises(TypeError):
            special_factorial([4])

