class TestDoubleTheDifference(unittest.TestCase):
    def test_all_positive_odds(self):
        self.assertEqual(double_the_difference([1, 3, 5]), 1 + 9 + 25)

    def test_positive_and_negative_odds(self):
        self.assertEqual(double_the_difference([1, -3, 5]), 1 + 25)

    def test_zeros_only(self):
        self.assertEqual(double_the_difference([0, 0, 0]), 0)

    def test_positives_with_even_numbers(self):
        self.assertEqual(double_the_difference([2, 4, 6]), 0)

    def test_mixed_types_ignore_floats(self):
        self.assertEqual(double_the_difference([1, 3.0, 5]), 1 + 25)

    def test_negative_and_positive_mixed(self):
        self.assertEqual(double_the_difference([-1, 3, 7]), 9 + 49)

    def test_empty_list(self):
        self.assertEqual(double_the_difference([]), 0)

    def test_large_numbers(self):
        self.assertEqual(double_the_difference([11, 21]), 121 + 441)

    def test_single_positive_odd(self):
        self.assertEqual(double_the_difference([7]), 49)

    def test_single_negative_odd(self):
        self.assertEqual(double_the_difference([-7]), 0)

    def test_float_numbers_ignored(self):
        self.assertEqual(double_the_difference([1.1, 3.3, 5.5]), 0)

    def test_string_in_list_ignored(self):
        self.assertEqual(double_the_difference([1, '3', 5]), 1 + 25)

    def test_zero_and_negative_ignored(self):
        self.assertEqual(double_the_difference([0, -1, -3]), 0)

    def test_large_mixed_list(self):
        self.assertEqual(double_the_difference([1, 2, 3, 4, 5, -7, 9, 10, 11]), 1 + 9 + 25 + 81 + 121)

    def test_non_integer_like_numbers(self):
